function dbEndingOf(){
  const ctx = envCtx();
  for(const e of dataOf('end')){
    try{ if(condOK(e.cond, ctx)) return {id: e.id, n: e.name, d: e.desc, origin: e.origin}; }catch(err){}
  }
  return null;
}
/* =========================================================
   内容库（事件 / 天赋 / 成就 / 结局 / 标签）
   —— 统一「外层信封 + 五类 item 字段」的数据规范，
      改动只写入覆盖层 DBX，内置数据永不被破坏。
   ========================================================= */
const DB_KEY = 'lr_db';   // 内容库：跨版本累积，不带版本号
const DBX_KINDS = {ev:'事件', tal:'天赋', ach:'成就', end:'结局', tag:'标签', epitaph:'墓志铭'};
let DBX = null;
function dbxDefault(){ return {ev:[], tal:[], ach:[], end:[], tag:[], epitaph:[]}; }
function dbxGet(){
  if(DBX) return DBX;
  try{ DBX = JSON.parse(lsCompat(DB_KEY, 'lr_db_') || 'null') || dbxDefault(); }catch(e){ DBX = dbxDefault(); }
  Object.keys(DBX_KINDS).forEach(k => { if(!Array.isArray(DBX[k])) DBX[k] = []; });
  return DBX;
}
/* 内容库任何一次落盘后，属性偏向缓存都必须失效：affJudge 的缓存键是
   「id + 文案长度」，同 id 覆盖写（长度不变）时会读到陈旧结果。 */
function dbxSet(){
  lsSet(DB_KEY, JSON.stringify(DBX || dbxDefault()));
  try{ affCacheClear(); }catch(e){}
  /* 内容库变了 → 事件派生字段（aff / req / sex）与阶段源池缓存全部失效，下次重算 */
  try{ evDeriveClear(); }catch(e){}
  try{ stageSrcClear(); }catch(e){}
}

