/* 内置数据（本地）。只认已登记的分类：拼错 kind 会直接把标签库当成该分类返回，
   属于「静默串味」，所以这里显式兜底到标签库并在控制台留一条告警。 */
function builtinOf(kind){
  if(kind === 'ev')  return builtinEv();
  if(kind === 'tal') return builtinTal();
  if(kind === 'ach') return builtinAch();
  if(kind === 'end') return builtinEnd();
  if(kind === 'epitaph') return builtinEpitaph();
  if(kind === 'tag') return builtinTag();
  try{ console.warn('builtinOf: 未登记的分类 ' + kind); }catch(e){}
  return [];
}
/* 按本局结局面貌挑一条墓志铭（先匹配专属结局 / 评级称号，再退到通用）。
   优先用「外部 + AI 加入」的条目，其次本地内置；同分时随机，避免每局一模一样。 */
function epitaphFor(ending, rank, tags, age){
  const all = dataOf('epitaph');
  if(!all.length) return null;
  const num = v => { const x = Number(v); return isFinite(x) ? x : null; };
  const scoreOfItem = it => {
    let s = 0;
    const t = String(it.tag || '');
    const end = String(it.ending || '');
    /* 结局命中只算一次：tag / ending 是同义字段，两个都写不该变成双倍分，
       否则本地条目（两个字段都填）会永远压过只填一个字段的「AI 加入」条目。 */
    if(((end && ending && end === ending) || (t && ending && t === ending))) s += 100;
    if(t && rank && t === rank) s += 80;                    // 命中 SSS/S/A/B/C/D/E 评级
    if(t && tags && tags.indexOf(t) >= 0) s += 60;          // 命中本局状态标签
    const a1 = num(it.ageMin), a2 = num(it.ageMax);
    if(age != null && a1 != null && age < a1) return -1;
    if(age != null && a2 != null && age > a2) return -1;
    if((it.__src == null ? 0 : it.__src) !== 0) s += 5;     // 用户自己的/AI 的优先于内置
    return s;
  };
  const scored = all.map(it => ({it: it, s: scoreOfItem(it)})).filter(o => o.s >= 0);
  if(!scored.length) return null;
  const mx = Math.max.apply(null, scored.map(o => o.s));
  let top = scored.filter(o => o.s === mx);
  /* 一条都没命中（mx === 0）时，只从「通用 / 没绑结局」的条目里挑兜底，
     别让一条恰好绑了别的结局的墓志铭被随机抽中 —— 那样读起来会离题。 */
  if(mx === 0){
    const generic = top.filter(o => { const k = String(o.it.tag || o.it.ending || ''); return !k || k === '通用'; });
    if(generic.length) top = generic;
  }
  return top[Math.floor(Math.random() * top.length)].it;
}
/* 内置 + 覆盖层（同 id 覆盖，_del 表示删除）
   【性能说明】这里刻意【不】缓存整个结果数组。
   dataOf 必须每次返回「全新的对象」，因为调用方（内容库页面 / 导入校验）会就地
   改写返回的元素 —— 一旦把缓存对象交出去，改动会留在缓存里污染后续所有调用。
   真正贵的是三项语义判定（affJudge / genReq / evSex），已由 evDerive() 缓存；
   剩下的 Object.assign 浅拷贝 4605 次只要 ~1.5ms，相比优化前的 67ms 已经够。
   实测（Node，240 次调用 = 一局 80 年 × 每年 3 件）：15395ms → 1408ms，快约 11 倍。 */
function dataOf(kind){
  /* 全量合并：遍历所有已知分类，把每条数据铺平 (不分 src) */
  if(kind === 'all'){
    let out = [];
    Object.keys(DBX_KINDS).forEach(k => { out = out.concat(dataOf(k)); });
    return out;
  }
  const base = builtinOf(kind);
  const extra = dbxList(kind);
  const byId = {}, order = [];
  // 内置 = 本地数据（只读、不可删除、不进备份）
  base.forEach(x => {
    const o = Object.assign({}, x);
    o.__src = 0;
    /* patch53 需求 3：本地事件也补上属性偏向 —— 否则内容库里几百条全落在「未标注」。
       推断规则与「外部 / AI 加入」完全同一套：效果键优先，文案关键词兜底。
       注意 aff 只用于展示与统计，不参与抽取权重（权重看 effects），不影响平衡。 */
    if(kind === 'ev'){
      /* 本地事件同样按这一套规则分类（运行时派生，不落盘）：
         aff = 讲的是哪一项隐藏子项；req = 什么样的人才会遇上它。
         三项派生结果统一走 evDerive() 缓存；数组再拷一份，防止调用方 push 改坏缓存。 */
      const d = evDerive(o);
      o.aff = d.aff.slice();
      if(!o.req) o.req = d.req;
      /* 需求 27：本地事件同样补上隐藏的「性别编号」（通用 / 男 / 女）。
         与 aff / req 一样是运行时派生，不落盘、不进导出。 */
      o.sex = d.sex;
    }
    byId[o.id] = o; order.push(o.id);
  });
  const baseIds = {};
  base.forEach(x => { baseIds[x.id] = 1; });
  extra.forEach(x => {
    if(!x || !x.id) return;
    // 双保险：指向「本地内置 id」的删除标记一律忽略，本地数据永不消失
    if(x._del){ if(!baseIds[x.id] && byId[x.id]) delete byId[x.id]; return; }
    const o = Object.assign({}, x);
    o.__src = (x.origin === 'ai') ? 2 : 1;   // 1 = 外部（含手动新增/导入），2 = AI 加入
    /* 需求 27：老数据 / 手写数据可能没带性别编号，这里统一兜底补一个 */
    if(kind === 'ev') o.sex = evSex(o);
    if(!byId[o.id]) order.push(o.id);
    byId[o.id] = o;
  });
  return order.filter(id => byId[id]).map(id => byId[id]);
}
/* 是否属于「只剩内置」的本地条目 —— 本地数据不可修改、不可删除 */
function isLocalOnly(kind, id){
  const ov = (dbxGet()[kind] || []).filter(x => x && x.id === id && !x._del);
  if(ov.length) return false;
  return builtinOf(kind).some(x => x.id === id);
}
function dbxList(kind){ const d = dbxGet(); return d[kind] || []; }
function dataPut(kind, item){
  withMode(item);
  const d = dbxGet();
  d[kind] = (d[kind] || []).filter(x => x.id !== item.id);
  d[kind].push(item);
  dbxSet();
}
/* ===== AI 生成防重复：与内容库（本地 / 外部 / AI 加入）比对 ===== */
/* 赋值 mode 字段：从 alloc 或默认 'earth' */
function withMode(it){ if(it && !it.mode) it.mode = (alloc && alloc.mode) || 'earth'; return it; }
let dbAvoidCache = null;
/* 取某阶段内容库里的全部文案，作为 AI 的「禁写清单」 */
function dbAvoidList(st){
  const seen = {}, out = [];
  dataOf('ev').forEach(x => {
    if(!x || x.stage !== st || !x.text) return;
    const t = String(x.text).replace(/\s+/g, ' ').trim();
    if(!t || seen[t]) return;
    seen[t] = 1; out.push(t);
  });
  return out;
}
/* 归一化后的禁写集合（带缓存；一局内内容库不变，AI 入库发生在结算时） */
function dbAvoid(st){
  if(!dbAvoidCache) dbAvoidCache = {};
  if(dbAvoidCache[st]) return dbAvoidCache[st];
  const norms = [];
  dbAvoidList(st).forEach(t => { const n = normTxt(t); if(n) norms.push(n); });
  dbAvoidCache[st] = norms;
  return norms;
}
/* 二元组 Dice 相似度（0-1）：够快也够用 */
function simRate(a, b){
  if(!a || !b) return 0;
  if(a === b) return 1;
  if(a.length < 2 || b.length < 2) return 0;
  const gram = s => { const o = {}; for(let i = 0; i + 2 <= s.length; i++) o[s.slice(i, i + 2)] = 1; return Object.keys(o); };
  const ga = gram(a), gb = gram(b);
  if(!ga.length || !gb.length) return 0;
  const set = {}; gb.forEach(k => { set[k] = 1; });
  let hit = 0; ga.forEach(k => { if(set[k]) hit++; });
  return (2 * hit) / (ga.length + gb.length);
}
/* 是否与内容库某条重复：完全相同 / 包含关系 / 相似度 ≥ 0.75 */
function dupWithLib(txt, st){
  const nk = normTxt(txt);
  if(!nk) return false;
  const box = dbAvoid(st);
  for(let i = 0; i < box.length; i++){
    const o = box[i];
    if(!o) continue;
    if(o === nk) return true;
    if(o.length >= 6 && nk.length >= 6 && (o.indexOf(nk) >= 0 || nk.indexOf(o) >= 0)) return true;
    if(simRate(o, nk) >= 0.75) return true;
  }
  return false;
}
/* 取一条数据用于比对的「主文本」 */
function dbMainText(kind, x){
  if(!x) return '';
  if(kind === 'ev' || kind === 'epitaph') return String(x.text || '');
  return String(x.name || '');
}

function dataDel(kind, id){
  if(isLocalOnly(kind, id)) return false;   // 本地内置数据：不可删除
  const d = dbxGet();
  d[kind] = (d[kind] || []).filter(x => x.id !== id);
  d[kind].push({id: id, _del: true});
  dbxSet();
  return true;
}
/* 文案归一化：去掉空白与标点后比较，避免「同义不同标点」被误判重复 */
function normTxt(s){
  return String(s == null ? '' : s).replace(/[\s\u3000]+/g, '').replace(/[，。！？、；：""''（）《》…—\-·,.!?;:'"()<>[\]{}]/g, '');
}
/* patch53 需求 1：内容库自净 —— 客户端里若存在与内置库文案重复的「外部 / AI 加入」条目，
   启动时自动清掉这些副本（升格成内置之后它们就是冗余的了）。
   只往覆盖层写 _del 标记，本地内置数据永远不碰；重复判定走 normTxt（忽略标点空白）。 */
function dbPurgeLocalDup(){
  const d = dbxGet();
  const list = d.ev || [];
  if(!list.length) return 0;
  const seen = {};
  builtinEv().forEach(x => { const k = normTxt(x.text); if(k) seen[k] = 1; });
  let n = 0;
  for(let i = 0; i < list.length; i++){
    const x = list[i];
    if(!x || x._del) continue;
    const k = normTxt(dbMainText('ev', x));
    if(!k || !seen[k]) continue;
    list[i] = {id: x.id, _del: true};
    n++;
  }
  if(n) dbxSet();
  return n;
}
/* 需求 7：把本局 AI 生成的事件文案收进内容库（来源标记为 AI 加入，下一局可被抽到） */
function collectAiToDb(){
  /* 需求 A：只由 flushAiDb() 在离开结算页时调用 —— 用户勾了才入库 */
  if(!S || !Array.isArray(S.aiMade) || !S.aiMade.length) return 0;
  const seen = {};
  dataOf('ev').forEach(x => { if(x && x.text) seen[normTxt(x.text)] = 1; });
  let n = 0;
  S.aiMade.forEach(it => {
    const full = String((it && it.t) || '');
    const t = full.slice(0, 140);
    const nk = normTxt(full);
    if(!t || !nk || seen[nk]) return;
    seen[nk] = 1;
    const ag = Math.max(0, Math.round(Number(it.age) || 0));
    const st = stageOf(ag);
    const rng = STAGE_RANGE[st] || [0, 3];
    const v = dbNorm('ev', {
      stage: st, age: [rng[0], rng[1]], weight: 5, text: t,
      effects: (it && it.e) || {}, simple: 'AI 生成并入库（第 ' + ag + ' 岁）', tags: []
    });
    /* 【修复】归一失败必须立刻退出：旧代码把 if(!v) 写在函数末尾，
       中间却已经 v.aff / v.sex / v.subs 地写字段，v 为 null 时会直接抛错，
       把整批 AI 文案的入库全部中断。 */
    if(!v) return;
    /* 需求 3：AI 事件的属性偏向一起落库，供「属性偏向判断」与后续抽题使用 */
    const af = sanAff(it && it.aff);
    if(af.length) v.aff = af;
    /* 需求 27：性别编号一起落库（dbNorm 已保证有值，这里用 AI 当时的判断覆盖） */
    const sx = sanSex(it && it.sex);
    if(sx) v.sex = sx;
    /* 【修复】AI 写的 subs（隐藏子项增减）与分支事件 o / 任务门槛 need 此前在入库时被削掉，
       于是「一键入库」收进来的 AI 文案永远只剩一句话，下一局再也不会弹选项。
       这里把三者一并规范化后落库：subs 走白名单、o 走 sanChoice、need 走 sanNeed。 */
    const sb = sanSubs(it && it.subs);
    if(sb) v.subs = sb;
    if(Array.isArray(it && it.o) && it.o.length){
      const oo = it.o.map(sanChoice).filter(Boolean);
      if(oo.length) v.o = oo;
    }
    const nd = sanNeed(it && it.need);
    if(nd) v.need = nd;
    v.origin = 'ai';
    dataPut('ev', v);
    n++;
  });
  S.aiMade = [];
  return n;
}

/* ---- 条件模板求值（需求 16：allMin / anyMin / maxAll / tags / age / ending + 生涯计数） ---- */
function envCtx(){
  const d = getDex();
  return {
    attr: (S && S.attr) ? S.attr : {},
    tags: (S && S.tags) ? S.tags : [],
    age: S ? Math.round(S.age) : 0,
    runs: d.runs || 0, best: d.best || 0,
    tagCnt: (d.tag || []).length, talCnt: (d.tal || []).length,
    ending: (S && S.ending) ? S.ending : '',
    achCnt: (d.ach || []).length,
    abyss: abyssTotal()
  };
}
function condOK(c, ctx){
  if(!c) return false;
  ctx = ctx || envCtx();
  const A = ctx.attr || {};
  if(c.runs != null && ctx.runs < c.runs) return false;
  if(c.best != null && ctx.best < c.best) return false;
  if(c.tagCnt != null && ctx.tagCnt < c.tagCnt) return false;
  if(c.talCnt != null && ctx.talCnt < c.talCnt) return false;
  if(c.ending && ctx.ending !== c.ending) return false;
  if(c.age){ if(ctx.age < c.age[0] || ctx.age > c.age[1]) return false; }
  if(c.tags){ for(const t of c.tags){ if((ctx.tags || []).indexOf(t) < 0) return false; } }
  if(c.notTags){ for(const t of c.notTags){ if((ctx.tags || []).indexOf(t) >= 0) return false; } }
  if(c.allMin){ for(const k in c.allMin){ if((A[k] || 0) < c.allMin[k]) return false; } }
  if(c.anyMin){
    let ok = false;
    for(const k in c.anyMin){ if((A[k] || 0) >= c.anyMin[k]){ ok = true; break; } }
    if(!ok) return false;
  }
  if(c.maxAll){ for(const k in c.maxAll){ if((A[k] || 0) > c.maxAll[k]) return false; } }
  if(c.achCnt != null && ctx.achCnt < c.achCnt) return false;
  if(c.abyss != null && ctx.abyss < c.abyss) return false;
  if(c.goldTal != null){
    let g = 0;
    (S && S.talents || []).forEach(id => { const t = talById(id); if(t && (t.r || 0) >= 2) g++; });
    if(g < c.goldTal) return false;
  }
  if(c.tagCntOneRun != null && (S && S.tags || []).length < c.tagCntOneRun) return false;
  if(c.ltAge != null){ if(!S || Math.round(S.age) > c.ltAge) return false; }
  return true;
}
/* 死亡结算那一刻统一检测成就（需求 16 定案：结算时才检测） */
function checkAch(){
  const ctx = envCtx(), d = getDex();
  d.ach = d.ach || [];
  const newly = [];
  dataOf('ach').forEach(a => {
    if(d.ach.indexOf(a.id) < 0 && condOK(a.cond, ctx)){ d.ach.push(a.id); newly.push(a.name); }
  });
  if(newly.length) setDex(d);
  return newly;
}
/* 已达成成就的属性加成（开局自动叠加） */
function achBonus(){
  const d = getDex(), out = {};
  dataOf('ach').forEach(a => {
    if((d.ach || []).indexOf(a.id) < 0 || !a.effects) return;
    for(const k in a.effects) out[k] = (out[k] || 0) + Number(a.effects[k] || 0);
  });
  return out;
}

/* =========================================================
   v0.0.2：AI 生成「天赋」与「结局」
   —— 天赋在开局抽卡时掺入；结局在死亡结算时按本局特点新增。
   两类都落进内容库（origin='ai'），下一局可被复用。
   生成频率同样受设置里的「AI 占比」滑条控制（0% 时完全不生成）。
   ========================================================= */
/* 当前 AI 占比目标（0~1） */
function aiRatioT(){
  try{ return clamp((getCfg().ai == null ? 50 : getCfg().ai) / 100, 0, 1); }catch(e){ return 0; }
}
/* ===== 天赋 / 结局 / 墓志铭 / 大纲 / 助手 共用的「超精简世界书」=====
   这三条路径都是低频、小输出（一次一两百 token），没必要每次都把整本世界书
   （含阶段边界、事件格式契约、交互事件规则）带上 —— 那些对「写一个天赋名」
   毫无用处，纯属把两千多字重复买很多遍。
   常量本体 WORLD_TINY 定义在 00-config.js（它最先加载，03-logic 的大纲生成也要用）。 */
/* 开局抽天赋时让 AI 补几个候选；生成结果入库后走 refreshTalExt() 进抽卡池。
   【节流】一次抽卡只允许生成一次，重复点「重抽」不会重复请求 ——
   以前每点一次重抽就发一次请求，玩家连点五下就是五次白烧。 */
let aiTalBusy = false, aiTalDone = false;
async function aiGenTalents(n){
  if(!aiReady() || aiRatioT() <= 0 || aiTalBusy || aiTalDone) return [];
  aiTalBusy = true;
  try{
    const raw = await callAI([
      {role:'system', content: WORLD_TINY + '\n【本次任务】你是这台模拟器的天赋设计师。只输出 JSON 数组，不要任何解释、不要代码块标记。'},
      {role:'user', content:
        '为这款人生模拟器设计 ' + n + ' 个全新天赋（开局可选，会影响整局走向）。\n' +
        '时代：' + (era && era.n ? era.n : '当代') + '。\n' +
        '要求：\n' +
        '1. 每个天赋按这个结构写：{"name":"四字名","rarity":0,"effects":{"CHR":2},"good":"利（15-25 字）","bad":"弊（15-25 字）"}\n' +
        '2. rarity：0 白 / 1 蓝 / 2 紫 / 3 橙，这一批以 0 和 1 为主，最多一个 2\n' +
        '3. effects 是开局属性增减，键只能是 CHR/INT/STR/MNY/LUK/SPR/SOC，值在 -3 到 3 之间\n' +
        '4. name 要短（2-6 字）、彼此不重复，别用「天生丽质」「富二代」这类烂大街的\n' +
        '5. good / bad 要具体、有画面感，写「利在哪、弊在哪」，不要写成数值说明\n' +
        '6. 绝不可与下列已有天赋重名：' + ALL_TALENTS.slice(0, 50).map(t => t.n).join('、')
    }], clamp(n * 150 + 200, 400, 1200));
    const arr = extractJSON(raw);
    if(!Array.isArray(arr)) return [];
    const out = [];
    arr.forEach(o => {
      if(!o || !o.name) return;
      const v = dbNorm('tal', {
        name: String(o.name).slice(0, 8),
        rarity: clamp(Number(o.rarity) || 0, 0, 3),
        effects: cleanEff(o.effects),
        good: String(o.good || '').slice(0, 40),
        bad: String(o.bad || '').slice(0, 40)
      });
      if(!v) return;
      v.origin = 'ai';
      dataPut('tal', v);
      out.push(v.id);
    });
    if(out.length) refreshTalExt();
    aiTalDone = true;      // 本局已经补过天赋，不再重复请求
    return out;
  }catch(e){ return []; }
  finally{ aiTalBusy = false; }
}
/* 抽天赋的统一入口：先给本地 6 个，AI 的回来了再追加进池子（不阻塞、不打断玩家） */
function rollTalentsSmart(n){
  alloc.poolIds = rollTalents(n || 6);
  alloc.picked = [];
  if(aiReady() && aiRatioT() > 0 && !aiTalDone){
    const g = gen;
    aiGenTalents(2).then(ids => {
      if(!ids || !ids.length || g !== gen) return;
      if(typeof CUR !== 'undefined' && CUR !== 'TALENT_SELECTION') return;
      ids.forEach(id => { if(alloc.poolIds.indexOf(id) < 0) alloc.poolIds.push(id); });
      try{ renderTalents(); }catch(e){}
      toast('AI 新写了 ' + ids.length + ' 个天赋');
    });
  }
}
/* 进入「新的一轮抽卡」时复位节流标记（点「重抽」不复位：同一轮不重复请求） */
function resetTalGen(){ aiTalDone = false; }
/* 死亡结算时：按这一局真实的面貌让 AI 新写一个专属结局 */
async function aiGenEnding(ctx){
  if(!aiReady() || aiRatioT() <= 0) return null;
  try{
    const raw = await callAI([
      {role:'system', content: WORLD_TINY + '\n【本次任务】你是这台模拟器的结局设计师。只输出 JSON 对象，不要任何解释、不要代码块标记。'},
      {role:'user', content:
        '为下面这个已经走完的人生，新写一个专属结局称号与描述。\n' + ctx + '\n' +
        '要求：\n' +
        '1. 只输出 {"name":"...","desc":"..."}\n' +
        '2. name 是 2-6 字的结局称号，要能一眼看出这一生最特别的地方\n' +
        '3. desc 是 15-40 字的一句话，克制、有余味，不要喊口号、不要煽情\n' +
        '4. 必须扣住上面这个人真实的数据与标签 —— 换一个人就不成立，才叫专属\n' +
        '5. 不要直接套用「人生赢家」「长寿老人」这类已有的通用称号'
    }], 300);
    const o = extractJSON(raw);
    if(!o || !o.name) return null;
    return {n: String(o.name).slice(0, 10), d: String(o.desc || '').slice(0, 60)};
  }catch(e){ return null; }
}

